import { mapState } from "vuex";
import goodsList from "@/components/goodsList";
import { liveGoodsCreat, liveGoodsAdd } from "@/api/live";
export default {
  name: "add_goods",
  components: {
    goodsList,
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 100;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  data() {
    return {
      isShowBox: false,
      loading: false,
      modals: false,
      goodsList: [],
      tempGoods: {},
      formValidate: {},
      columns1: [
        { key: "id", title: "商品ID", width: 80 },
        { slot: "img", title: "商品信息", minWidth: 250 },
        {
          key: "price",
          title: "直播售价",
          minWidth: 100,
          render: (h, params) => {
            return h("Input", {
              props: {
                type: "number",
                value: params.row.price,
              },
              on: {
                input: (val) => {
                  this.tabList[params.index].price = val;
                },
              },
            });
          },
        },
        {
          key: "cost_price",
          title: "划线价",
          minWidth: 100,
          render: (h, params) => {
            return h("Input", {
              props: {
                type: "number",
                value: params.row.cost_price,
              },
              on: {
                input: (val) => {
                  this.tabList[params.index].cost_price = val;
                },
              },
            });
          },
        },
        { key: "stock", title: "库存", minWidth: 80 },
        { slot: "action", fixed: "right", title: "操作", width: 100 },
      ],
      tabList: [],
    };
  },
  methods: {
    // 生成直播商品
    liveGoods() {
      let array = [];
      this.goodsList.map((el) => {
        array.push(el.product_id);
      });
      liveGoodsCreat({
        product_id: array,
      })
        .then((res) => {
          this.tabList = res.data;
          this.isShowBox = true;
        })
        .catch((error) => {
          this.$Message.error(error.msg);
        });
    },
    //对象数组去重；
    unique(arr) {
      const res = new Map();
      return arr.filter(
        (arr) => !res.has(arr.product_id) && res.set(arr.product_id, 1)
      );
    },
    getProductId(data) {
      let list = this.goodsList.concat(data);
      let uni = this.unique(list);
      this.goodsList = uni;
      this.$nextTick((res) => {
        setTimeout(() => {
          this.modals = false;
        }, 300);
      });
    },
    bindDelete(index) {
      this.goodsList.splice(index, 1);
    },
    del(row, index) {
      this.tabList.splice(index, 1);
    },
    // 提交
    bindSub() {
      liveGoodsAdd({
        goods_info: this.tabList,
      })
        .then((res) => {
          this.$Message.success("添加成功");
          setTimeout(() => {
            this.$router.push({ path: "/admin/content/live/live_goods" });
          }, 500);
        })
        .catch((error) => {
          this.$Message.error(error.msg);
        });
    },
  },
};
